'use strict';
// Golden vectors are derived from pinned reference source, not generated by this implementation.
const assert=require('node:assert/strict'), F=require('./lanplay-fork'), L=require('./lanplay');
const {ldn}=require('./test-lanplay-fork');
const scan=Buffer.from('001445110000000000001100','hex');
assert.deepEqual(ldn(0),scan);
const frame=Buffer.from('00144511010104000500110001000202','hex');
assert.deepEqual(ldn(1,Buffer.from('0100000002','hex')),frame);
const parsed=L.ldnRead({},frame);assert.equal(parsed.length,1);assert.equal(parsed[0].type,1);assert.equal(parsed[0].seq,17);assert.deepEqual(parsed[0].data,Buffer.from('0100000002','hex'));
const body=F.wrap(0xc0a8012a,0xc0a80233,Buffer.from('xyz'));
assert.equal(body.toString('hex'),'c0a8012ac0a8023378797a');
const base=Buffer.from('4500002700004000401100000a0d01020a0d03043039303900130000c0a8012ac0a8023378797a','hex');
assert.equal(F.addIpId(base,F.GAME_V2).toString('hex'),'45000027474e40004011db580a0d01020a0d03043039303900130000c0a8012ac0a8023378797a');
assert.deepEqual(F.unwrap(F.GAME_V2,body),{realSrc:0xc0a8012a,realDst:0xc0a80233,data:Buffer.from('xyz')});
assert.equal(F.unwrap(F.GAME_V2,Buffer.alloc(7)),null);assert.equal(F.wrap(1,2,Buffer.alloc(1473)),null);
const n=Buffer.alloc(0x480);n[0x10]=1;n[0x20]=1;n[0x66]=3;n[0x67]=1;n[0x68+11]=1;n.writeUInt32LE(0xc0a8012a,0x68);
assert(F.identity(n));const normalized=F.normalize(n,()=>0x0a0d0102);assert.equal(normalized.readUInt32LE(0x68),0x0a0d0102);
const dup=Buffer.from(n);dup[0x67]=2;dup[0x68+0x40+10]=1;dup[0x68+0x40+11]=1;dup.writeUInt32LE(0xc0a8012a,0x68+0x40);assert.equal(F.identity(dup),null);assert.equal(F.normalize(dup,()=>0x0a0d0102),null);
const badCount=Buffer.from(n);badCount[0x67]=4;assert.equal(F.identity(badCount),null);
const wrongCount=Buffer.from(n);wrongCount[0x67]=2;assert.equal(F.identity(wrongCount),null);
console.log('Fork reference golden headers, RLE, checksum, shim and malformed NetworkInfo passed');
